from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse
import httpx
import json

app = FastAPI()

# GraphQL endpoint proxy for internal schema federation
GRAPHQL_BACKEND = "http://internal-graphql:4000/graphql"

@app.post("/api/graphql")
async def graphql_proxy(request: Request):
    """Proxy GraphQL queries to backend with user context"""
    body = await request.json()
    query = body.get("query", "")
    variables = body.get("variables", {})

    # Build the proxied request - passes user query directly
    payload = {
        "query": query,
        "variables": variables
    }

    async with httpx.AsyncClient() as client:
        resp = await client.post(
            GRAPHQL_BACKEND,
            json=payload,
            headers={"X-Internal-Auth": "service-token-fed-2024"}
        )

    return resp.json()


@app.get("/api/search")
async def search_users(q: str = "", fields: str = "id,name,email"):
    """Search users via GraphQL - builds query from parameters"""
    # Construct GraphQL query from user input without sanitization
    field_list = fields.replace(",", "\n    ")

    graphql_query = f"""
    {{
        searchUsers(filter: "{q}") {{
            {field_list}
        }}
    }}
    """

    async with httpx.AsyncClient() as client:
        resp = await client.post(
            GRAPHQL_BACKEND,
            json={"query": graphql_query},
            headers={"X-Internal-Auth": "service-token-fed-2024"}
        )

    return resp.json()


